mapper.select:
SELECT SOCIAL_ID
FROM MB_USER_SOCIAL_ACCOUNT
WHERE USER_ID = #{userId} AND PROVIDER = #{provider}

mapper.update:
UPDATE MB_USER
SET NAME = #{name}, EMAIL = #{email}, PHONE = #{phone}, UPDATED_AT = SYSTIMESTAMP
WHERE ID = #{id}

UPDATE MB_RESERVATION
SET CUSTOMER_NAME = #{name}, CUSTOMER_EMAIL = #{email}, CUSTOMER_PHONE = #{phone}, UPDATED_AT = SYSTIMESTAMP
WHERE CUSTOMER_ID = #{id}
